// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type ScoringSystemProps = Record<string, any>;

const ScoringSystem: React.FC<ScoringSystemProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,
  accentColor = "#00e5ff",
  textColor = "#ffffff",
  textPart1 = "WE SCORE EACH DARE...",
  textPart2 = "ON A 1 TO 5 SCALE",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Baseline layout math
  const boxW = width * 0.08;
  const boxH = boxW * 1.3;
  const gap = width * 0.02;
  const totalFrames = durationInSeconds * fps;

  // Colors & Styles
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const dullColor = "#222222";
  const darkPanelColor = "#111111";

  // Timeline Markers
  const t1Start = 10;
  const glitchCutStart = 46;
  const t2Start = 50;
  const glitchCutEnd = 52;
  const boxesStart = 60;
  const cursorStart = 90;
  const clickFrame = 105;
  const zoomStart = totalFrames - 15;

  // Global Glitch Logic
  const isIntroGlitch = frame >= 0 && frame < 6;
  const isCutGlitch = frame >= glitchCutStart && frame < glitchCutEnd;
  const isGlitching = isIntroGlitch || isCutGlitch;

  const glitchX = isGlitching ? interpolate(random(`gx-${frame}`), [0, 1], [-30, 30]) : 0;
  const glitchY = isGlitching ? interpolate(random(`gy-${frame}`), [0, 1], [-15, 15]) : 0;
  const glitchShadow = isGlitching
    ? `${interpolate(random(`s1-${frame}`), [0, 1], [-10, 10])}px ${interpolate(
        random(`s2-${frame}`),
        [0, 1],
        [-5, 5]
      )}px 0 rgba(255,0,80,0.8), ${interpolate(
        random(`s3-${frame}`),
        [0, 1],
        [-10, 10]
      )}px ${interpolate(random(`s4-${frame}`), [0, 1], [-5, 5])}px 0 rgba(0,229,255,0.8)`
    : "none";

  // Screen Shake (on click)
  const isShaking = frame >= clickFrame && frame < clickFrame + 8;
  const shakeX = isShaking ? interpolate(random(`shx-${frame}`), [0, 1], [-20, 20]) : 0;
  const shakeY = isShaking ? interpolate(random(`shy-${frame}`), [0, 1], [-15, 15]) : 0;

  // End Zoom Transition (targeting the "5" box)
  const originX = width / 2 + 2 * (boxW + gap); // center of the 5th box
  const originY = height * 0.55 + boxH / 2;
  
  const endZoom = interpolate(frame, [zoomStart, totalFrames], [1, 12], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const endOpacity = interpolate(frame, [zoomStart + 8, totalFrames], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Master Transforms
  const masterX = glitchX + shakeX;
  const masterY = glitchY + shakeY;

  // Text 1 Animation
  const t1Spring = spring({ fps, frame: frame - t1Start, config: { damping: 14 } });
  const t1Y = interpolate(t1Spring, [0, 1], [40, 0]);
  const t1Opacity = interpolate(frame, [t1Start, t1Start + 5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Text 2 Animation
  const t2Spring = spring({ fps, frame: frame - t2Start, config: { damping: 14 } });
  const t2Y = interpolate(t2Spring, [0, 1], [40, 0]);
  const t2Opacity = interpolate(frame, [t2Start, t2Start + 5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Cursor Path Calculation
  const cursorMove = spring({
    fps,
    frame: frame - cursorStart,
    config: { damping: 15, stiffness: 120 },
  });
  const cursorX = interpolate(cursorMove, [0, 1], [width * 0.8, originX]);
  const cursorY = interpolate(cursorMove, [0, 1], [height * 0.9, originY]);
  
  const cursorClickScale = spring({
    fps,
    frame: frame - clickFrame,
    config: { damping: 10, stiffness: 300 },
  });
  const cursorScale = 1 - cursorClickScale * 0.2; // Shrinks slightly on tap
  const cursorOpacity = interpolate(frame, [zoomStart, zoomStart + 5], [1, 0], { extrapolateRight: "clamp" });

  // Reusable SVG Star
  const StarIcon = ({ color }: { color: string }) => (
    <svg viewBox="0 0 24 24" fill={color} style={{ width: "35%", height: "35%", marginTop: "10%" }}>
      <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" />
    </svg>
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* Background Subtle Radial Glow */}
      <svg width="100%" height="100%" style={{ position: "absolute", opacity: 0.15 }}>
        <defs>
          <radialGradient id="bgGlow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor={accentColor} />
            <stop offset="100%" stopColor="transparent" />
          </radialGradient>
        </defs>
        <rect width="100%" height="100%" fill="url(#bgGlow)" />
      </svg>

      {/* Main Animated Wrapper */}
      <AbsoluteFill
        style={{
          transformOrigin: `${originX}px ${originY}px`,
          transform: `translate(${masterX}px, ${masterY}px) scale(${endZoom})`,
          opacity: endOpacity,
          transition: "none",
        }}
      >
        {/* Texts container */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            top: height * 0.3,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          {frame < t2Start ? (
            <h1
              style={{
                fontSize: width * 0.05,
                fontWeight: 900,
                color: isGlitching && random(`tc-${frame}`) > 0.5 ? accentColor : textColor,
                textTransform: "uppercase",
                letterSpacing: "0.05em",
                margin: 0,
                opacity: t1Opacity,
                transform: `translateY(${t1Y}px)`,
                textShadow: glitchShadow,
                transition: "none",
              }}
            >
              {textPart1}
            </h1>
          ) : (
            <h1
              style={{
                fontSize: width * 0.05,
                fontWeight: 900,
                color: isGlitching && random(`tc2-${frame}`) > 0.5 ? accentColor : textColor,
                textTransform: "uppercase",
                letterSpacing: "0.05em",
                margin: 0,
                opacity: t2Opacity,
                transform: `translateY(${t2Y}px)`,
                textShadow: glitchShadow,
                transition: "none",
              }}
            >
              {textPart2}
            </h1>
          )}
        </div>

        {/* Rating Scale Container */}
        <div
          style={{
            position: "absolute",
            top: height * 0.55,
            width: "100%",
            display: "flex",
            flexDirection: "row",
            justifyContent: "center",
            gap: `${gap}px`,
          }}
        >
          {[1, 2, 3, 4, 5].map((num, i) => {
            const isFive = num === 5;
            const popFrame = boxesStart + i * 4;
            const popSpring = spring({ fps, frame: frame - popFrame, config: { damping: 12 } });

            // Quick white flash when box pops in
            const flashOpacity = interpolate(
              frame,
              [popFrame, popFrame + 3, popFrame + 8],
              [0, 1, 0],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            // Click reaction exactly on box 5
            const popReaction = isFive
              ? spring({ fps, frame: frame - clickFrame, config: { damping: 10 } })
              : 0;

            // Continuous pulse after click on box 5
            const pulse =
              isFive && frame > clickFrame
                ? Math.sin((frame - clickFrame) * 0.25) * 0.05
                : 0;

            const baseScale = interpolate(popSpring, [0, 1], [0, 1]);
            const boxScale = baseScale + (isFive ? popReaction * 0.15 + pulse : 0);

            // Color logic: low ratings dull, 5 becomes glowing blue at clickFrame
            const isGlowing = isFive && frame >= clickFrame;
            const currentBorderColor = isGlowing ? accentColor : dullColor;
            const currentGlowShadow = isGlowing ? `0 0 45px ${accentColor}80` : "none";

            return (
              <div
                key={num}
                style={{
                  width: `${boxW}px`,
                  height: `${boxH}px`,
                  backgroundColor: darkPanelColor,
                  borderRadius: "20px",
                  border: `3px solid ${currentBorderColor}`,
                  boxShadow: currentGlowShadow,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "center",
                  transform: `scale(${boxScale})`,
                  position: "relative",
                  overflow: "hidden",
                  transition: "none",
                }}
              >
                <span
                  style={{
                    fontSize: boxW * 0.5,
                    fontWeight: 900,
                    color: isGlowing ? accentColor : textColor,
                    lineHeight: 1,
                    textShadow: isGlowing ? `0 0 20px ${accentColor}` : "none",
                  }}
                >
                  {num}
                </span>
                <StarIcon color={isGlowing ? accentColor : dullColor} />

                {/* Pop Flash Overlay */}
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    backgroundColor: "#ffffff",
                    opacity: flashOpacity,
                    pointerEvents: "none",
                    transition: "none",
                  }}
                />
              </div>
            );
          })}
        </div>
      </AbsoluteFill>

      {/* Fake Cursor overlay */}
      {frame >= cursorStart && (
        <div
          style={{
            position: "absolute",
            left: `${cursorX}px`,
            top: `${cursorY}px`,
            transform: `scale(${cursorScale})`,
            transformOrigin: "top left",
            zIndex: 50,
            opacity: cursorOpacity,
            pointerEvents: "none",
            transition: "none",
          }}
        >
          <svg
            width="60"
            height="60"
            viewBox="0 0 24 24"
            fill="white"
            stroke="black"
            strokeWidth="1.5"
            style={{
              filter: "drop-shadow(0px 10px 15px rgba(0,0,0,0.5))",
            }}
          >
            <path d="M5.5 3.21V20.8c0 .45.54.67.85.35l4.86-4.86a.5.5 0 0 1 .35-.15h6.42c.45 0 .67-.54.35-.85L6.35 2.86a.5.5 0 0 0-.85.35z" />
          </svg>
        </div>
      )}
    </AbsoluteFill>
  );
};

export default ScoringSystem;